static uint8_t s_product_pixels_1[FUI_PRODUCT_STRIDE_1 * FUI_PRODUCT_HEIGHT_1];
static vg_lite_buffer_t s_product_atlas_1;

static bool s_product_ready;

static void product_font_init(void)
{
    if (s_product_ready) return;
    memcpy(s_product_pixels_1, s_product_source_1, sizeof(s_product_pixels_1));
    memset(&s_product_atlas_1, 0, sizeof(s_product_atlas_1));
    s_product_atlas_1.width = FUI_PRODUCT_STRIDE_1;
    s_product_atlas_1.height = FUI_PRODUCT_HEIGHT_1;
    s_product_atlas_1.stride = FUI_PRODUCT_STRIDE_1;
    s_product_atlas_1.format = VG_LITE_A8;
    s_product_atlas_1.tiled = VG_LITE_LINEAR;
    s_product_atlas_1.image_mode = VG_LITE_MULTIPLY_IMAGE_MODE;
    s_product_atlas_1.transparency_mode = VG_LITE_IMAGE_TRANSPARENT;
    s_product_atlas_1.memory = s_product_pixels_1;
    s_product_atlas_1.address = (uint32_t)(uintptr_t)s_product_pixels_1;
    s_product_ready = true;
}

uint16_t fui_font_scale_dimension(uint16_t base, uint8_t text_scale)
{
    if (text_scale >= 3U) return (uint16_t)((base * 3U + 1U) / 2U);
    if (text_scale == 2U) return base;
    return (uint16_t)((base * 3U + 2U) / 4U);
}

uint8_t fui_font_line_height(uint8_t text_scale)
{
    return (uint8_t)fui_font_scale_dimension(FUI_PRODUCT_CELL_1, text_scale);
}

bool fui_font_glyph_get(uint32_t codepoint, uint8_t text_scale, fui_font_glyph_t *glyph)
{
    uint32_t low = 0U;
    uint32_t high = FUI_PRODUCT_GLYPH_COUNT;
    uint32_t index;
    uint8_t cell;
    if (glyph == RT_NULL) return false;
    while (low < high)
    {
        uint32_t middle = low + (high - low) / 2U;
        if (s_product_codes[middle] < codepoint) low = middle + 1U;
        else high = middle;
    }
    if (low >= FUI_PRODUCT_GLYPH_COUNT || s_product_codes[low] != codepoint)
    {
        codepoint = (uint32_t)'?';
        low = 0U;
        high = FUI_PRODUCT_GLYPH_COUNT;
        while (low < high)
        {
            uint32_t middle = low + (high - low) / 2U;
            if (s_product_codes[middle] < codepoint) low = middle + 1U;
            else high = middle;
        }
        if (low >= FUI_PRODUCT_GLYPH_COUNT || s_product_codes[low] != codepoint) return false;
    }
    index = low;
    product_font_init();
    (void)text_scale;
    cell = FUI_PRODUCT_CELL_1;
    glyph->atlas = &s_product_atlas_1;
    glyph->advance = s_product_advance_1[index];
    glyph->source_x = (uint16_t)((index % FUI_PRODUCT_COLUMNS) * cell);
    glyph->source_y = (uint16_t)((index / FUI_PRODUCT_COLUMNS) * cell);
    glyph->width = cell;
    glyph->height = cell;
    return true;
}
